package com.cashflow.app.engine

import java.time.DayOfWeek
import java.time.LocalDate
import java.time.YearMonth

/** One stored row of a day as the day sheet lists it. */
data class DayItem(
    val tx: Transaction,
    /** Generated from a repeating payment / income source (it has a rule). */
    val fromSeries: Boolean,
    /** Generated by a DAILY income source: listed, but never shown in the month cells. */
    val dailyIncome: Boolean,
)

/**
 * Everything the calendar cell and the day sheet need for one date. All amounts are taken from the
 * engine's forecast, never recomputed: [expenses] and [closing] are the forecast's own numbers.
 */
data class DaySummary(
    val date: LocalDate,
    /** false for the leading/trailing days of the neighbouring months shown in the grid. */
    val inMonth: Boolean,
    val isToday: Boolean,
    val isPast: Boolean,
    /** false before the balance's start date: there is no forecast, so no closing balance. */
    val hasForecast: Boolean,
    /** Non-skipped expenses of the day (forecast.expenses). */
    val expenses: Long,
    /** Non-skipped income of the day without DAILY income-source items (those would be on every cell). */
    val shownIncome: Long,
    /** The forecast's closing balance of the day. */
    val closing: Long,
    val negative: Boolean,
    /** PENDING items dated today or earlier: they are waiting for an answer. */
    val waiting: Int,
    /** Every stored row of the day, SKIPPED ones included. */
    val items: List<DayItem>,
) {
    val hasExpenses get() = expenses > 0
    val hasIncome get() = shownIncome > 0
}

data class MonthSummary(val month: YearMonth, val weeks: List<List<DaySummary>>) {
    fun day(date: LocalDate): DaySummary? = weeks.firstNotNullOfOrNull { week -> week.firstOrNull { it.date == date } }
}

object CalendarSummaries {
    /** Summaries of the whole grid of [month] (5 or 6 rows), built from the engine's forecast. */
    fun month(
        engine: BalanceEngine,
        rules: List<RecurringRule>,
        month: YearMonth,
        firstDayOfWeek: DayOfWeek,
        minRows: Int = CalendarGrid.MIN_ROWS,
    ): MonthSummary {
        val grid = CalendarGrid.weeks(month, firstDayOfWeek, minRows)
        val from = grid.first().first()
        val to = grid.last().last()
        val forecast = engine.forecast(from, to).associateBy { it.date }
        val dailyRuleIds = rules.filter { it.pattern == RecurrencePattern.Daily && it.kind == TxKind.INCOME }.map { it.id }.toSet()
        val today = engine.today
        val weeks = grid.map { week ->
            week.map { date -> summarize(forecast[date], date, month, today, dailyRuleIds) }
        }
        return MonthSummary(month, weeks)
    }

    private fun summarize(f: DayForecast?, date: LocalDate, month: YearMonth, today: LocalDate, dailyRuleIds: Set<Long>): DaySummary {
        val items = f?.items.orEmpty().map {
            DayItem(
                tx = it,
                fromSeries = it.recurringRuleId != null,
                dailyIncome = it.source == TxSource.RECURRING && it.kind == TxKind.INCOME && it.recurringRuleId in dailyRuleIds,
            )
        }
        val live = items.filter { it.tx.status != TxStatus.SKIPPED }
        val shownIncome = live.filter { it.tx.kind == TxKind.INCOME && !it.dailyIncome }.sumOf { it.tx.amount }
        val waiting = live.count { it.tx.status == TxStatus.PENDING && !it.tx.date.isAfter(today) }
        return DaySummary(
            date = date,
            inMonth = YearMonth.from(date) == month,
            isToday = date == today,
            isPast = date.isBefore(today),
            hasForecast = f != null,
            expenses = f?.expenses ?: 0,
            shownIncome = shownIncome,
            closing = f?.closing ?: 0,
            negative = f != null && f.closing < 0,
            waiting = waiting,
            items = items,
        )
    }

    /** The first day (today or later) whose closing balance is negative; null when there is none. */
    fun firstShortDay(engine: BalanceEngine): LocalDate? = engine.negativeDays().firstOrNull()
}

/** Short amount text for a calendar cell: exact below 1000 TND, "1.3k" style above. No sign, no currency. */
object CompactAmount {
    fun format(millimes: Long): String {
        val abs = if (millimes < 0) -millimes else millimes
        if (abs < 1_000_000) return Money.format(Money.roundToCents(abs), withCurrency = false)
        if (abs < 1_000_000_000) return scaled(abs, 100_000L, 10_000_000L, 1_000_000L, "k")
        return scaled(abs, 100_000_000L, 10_000_000_000L, 1_000_000_000L, "M")
    }

    /** Units of 100 TND (or 100k) with one decimal below 10 units, whole units above. */
    private fun scaled(abs: Long, tenth: Long, tenUnits: Long, unit: Long, suffix: String): String {
        if (abs < tenUnits) {
            val tenths = (abs + tenth / 2) / tenth
            val text = if (tenths % 10 == 0L) "${tenths / 10}" else "${tenths / 10}.${tenths % 10}"
            return text + suffix
        }
        return "${(abs + unit / 2) / unit}$suffix"
    }

    /** A balance: "135", "1.2k", and "-10" when negative (red in the cell). */
    fun balance(millimes: Long): String = (if (millimes < 0) "-" else "") + format(millimes)

    /** "-75" / "+30". */
    fun signed(kind: TxKind, millimes: Long): String = (if (kind == TxKind.INCOME) "+" else "-") + format(millimes)
}
